import {MOVES} from './combat-moves.mjs';
import {profile,level,stats,equippedMoves} from './training.mjs';
import {bestIVs} from './genetics.mjs';
import {heldItems,normalizeEquipment} from './model.mjs';
import * as Art from './art.mjs';
export function evolutionRequirements(dex,state,key,rule,now=new Date()){
 const d=dex[parseInt(key)],p=profile(state,key),c=rule.conditions||{},moves=equippedMoves(d,p),missing=[];
 if(!dex[rule.id]||(key.endsWith('s')&&!dex[rule.id].shiny))missing.push('Sprite de cette variante indisponible');
 if(level(p)<rule.level)missing.push('Niveau '+rule.level);
 for(const item of rule.items||[])if(!(state.bag?.[item]>0))missing.push(item);
 if(c.time){const hour=+new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',hour:'2-digit',hourCycle:'h23'}).format(now),day=hour>=6&&hour<20;if((c.time==='day')!==day)missing.push(c.time==='day'?'En journée (6 h – 20 h, Paris)':'De nuit (20 h – 6 h, Paris)')}
 if(c.move&&!moves.some(m=>m.id===c.move))missing.push('Équiper '+(MOVES[c.move]?.name||'la capacité #'+c.move));if(c.moveType&&!moves.some(m=>m.type===c.moveType))missing.push('Équiper une capacité de type '+(Art.TYPE_NAMES[c.moveType]||c.moveType));
 if(c.relativeStats!==undefined&&c.relativeStats!==null){const s=stats(dex,key,p);if(Math.sign(s[1]-s[2])!==c.relativeStats)missing.push(c.relativeStats===0?'Attaque = Défense':c.relativeStats>0?'Attaque > Défense':'Attaque < Défense')}
 if(c.partySpecies&&!state.team.some(k=>parseInt(k)===c.partySpecies))missing.push('Avoir '+(dex[c.partySpecies]?.name||'#'+c.partySpecies)+' dans l’équipe');if(c.partyType&&!state.team.some(k=>dex[parseInt(k)]?.types.includes(c.partyType)))missing.push('Un partenaire '+(Art.TYPE_NAMES[c.partyType]||c.partyType)+' dans l’équipe');return missing;
}
export function evolvePokemon(dex,state,key,rule,now=new Date()){
 if(!state.roster.includes(key)||!dex[parseInt(key)]?.evolutions?.some(e=>e===rule||JSON.stringify(e)===JSON.stringify(rule))||evolutionRequirements(dex,state,key,rule,now).length)return null;
 const next=String(rule.id)+(key.endsWith('s')?'s':''),source=profile(state,key),sourceD=dex[parseInt(key)],targetD=dex[rule.id],oldMoves=equippedMoves(sourceD,source).map(m=>m.id).filter(id=>id!==165),exists=state.roster.includes(next),prior=exists?profile(state,next):null,hidden=sourceD.abilities?.[source.ability]?.hidden;
 for(const item of rule.items||[])state.bag[item]--;
 const result={...source,iv:exists?bestIVs(source.iv,prior.iv):[...source.iv],ev:[...source.ev],xp:Math.max(source.xp,prior?.xp||0),moves:oldMoves,taughtMoves:[...new Set([...(source.taughtMoves||[]),...(prior?.taughtMoves||[])])],retainedMoves:[...new Set([...(source.retainedMoves||[]),...(prior?.retainedMoves||[]),...oldMoves])],ability:Math.max(0,targetD.abilities?.findIndex(a=>!!a.hidden===!!hidden)??0)};delete result.evolutionDeclinedLevel;
 state.training[next]=result;delete state.training[key];if(String(state.starter)===key)state.starter=rule.id;state.roster=[...new Set(state.roster.map(k=>k===key?next:k))];state.team=[...new Set(state.team.map(k=>k===key?next:k))];if(state.survivor===key)state.survivor=next;
 const gear=[...heldItems(state,key),...heldItems(state,next)],unique=[];for(const i of gear)if(!unique.some(x=>x.key===i.key)&&unique.length<3)unique.push(i);delete state.equipment[key];const slots=[null,null,null];for(const i of unique){const slot=!slots[i.slot]?i.slot:slots.findIndex(v=>!v);if(slot>=0)slots[slot]=i.uid}state.equipment[next]=slots;state.equipment=normalizeEquipment(state);
 state.shinyCopies||={};if(key.endsWith('s')){state.shinyCopies[next]=(exists?state.shinyCopies[next]||1:0)+(state.shinyCopies[key]||1);delete state.shinyCopies[key]}
 for(const id of rule.bonus||[]){const k=String(id)+(key.endsWith('s')?'s':'');if(!dex[id]||(k.endsWith('s')&&!dex[id].shiny)||state.roster.includes(k))continue;state.roster.push(k);state.training[k]={...result,ev:[...result.ev],iv:[...result.iv],moves:[...result.moves],taughtMoves:[...result.taughtMoves],retainedMoves:[...result.retainedMoves],ability:0};if(k.endsWith('s'))state.shinyCopies[k]=1}
 state.evolutionChecks=(state.evolutionChecks||[]).filter(k=>k!==key);if(targetD.evolutions?.some(e=>e.method==='level'&&!evolutionRequirements(dex,state,next,e,now).length))state.evolutionChecks.push(next);return next;
}
export class EvolutionManager{
 constructor(g){this.g=g;setInterval(()=>this.pump(),1200)}
 labels(rule){return ['Niv. '+rule.level,...(rule.items||[]).map(k=>this.g.shop.catalog.find(i=>i.key===k)?.name||k),...(rule.conditions?.time?[rule.conditions.time==='day'?'De jour':'De nuit']:[]),...(rule.conditions?.move?['Équiper '+(MOVES[rule.conditions.move]?.name||'#'+rule.conditions.move)]:[]),...(rule.conditions?.moveType?['Capacité '+(Art.TYPE_NAMES[rule.conditions.moveType]||rule.conditions.moveType)]:[])]}
 panel(key){const g=this.g,rules=g.poke(key).evolutions||[];return `<h4>Évolutions</h4>${rules.map((e,i)=>{const missing=evolutionRequirements(g.dex,g.state,key,e);return `<div class="evolution-option">${g.image(String(e.id)+(key.endsWith('s')?'s':''))}<div><b>${g.dex[e.id]?.name}</b><small>${this.labels(e).join(' · ')}</small><small>${missing.length?missing.map(k=>g.shop.catalog.find(i=>i.key===k)?.name||k).join(' · '):'Prêt à évoluer !'}</small></div><button class="${missing.length?'':'primary'}" data-act="evolution-start" data-key="${key}" data-index="${i}" ${missing.length?'disabled':''}>Évoluer</button></div>`}).join('')||'<p>Ce Pokémon a atteint sa forme finale disponible.</p>'}<small>L’XP, les meilleurs IV, l’entraînement et les objets sont conservés. Les conditions spéciales des jeux sont adaptées avec les objets indiqués.</small>`}
 pump(){const g=this.g;if(this.busy||g.mode||g.modal.open||g.summoning.busy)return;const queue=g.state.evolutionChecks||[];while(queue.length){const key=queue.shift();if(!g.state.roster.includes(key))continue;const p=profile(g.state,key);if(p.evolutionDeclinedLevel===level(p))continue;const ready=(g.poke(key).evolutions||[]).map((e,index)=>({e,index})).filter(({e})=>e.method==='level'&&!evolutionRequirements(g.dex,g.state,key,e).length);g.save();if(ready.length===1){this.start(key,ready[0].index);return}if(ready.length>1){g.lab.key=key;g.lab.tab='level';g.lab.open(key);g.toast('Plusieurs évolutions sont possibles : choisis sa forme.');return}}}
 start(key,index){const g=this.g,rule=g.poke(key).evolutions?.[index];if(this.busy||g.mode||g.summoning.busy||!rule||evolutionRequirements(g.dex,g.state,key,rule).length)return;this.busy=true;const next=String(rule.id)+(key.endsWith('s')?'s':''),duration=g.state.settings.reducedMotion?350:2600;this.pending={key,index};Art.preload([key,next]);g.openModal(`<div class="evolution-scene"><span class="eyebrow">UN NOUVEAU CHAPITRE</span><h2>Quoi ? ${g.poke(key).name} évolue !</h2><div class="evolution-aura"></div><canvas width="360" height="300" aria-label="Évolution du Pokémon"></canvas><p>Son lien avec toi lui donne une nouvelle force.</p><button data-act="evolution-cancel">Conserver cette forme</button></div>`,{locked:true,className:'evolution-dialog'});const canvas=g.modal.querySelector('canvas'),ctx=canvas.getContext('2d'),start=performance.now();const draw=t=>{if(!this.pending||!canvas.isConnected)return;const p=Math.min(1,(t-start)/duration);ctx.clearRect(0,0,360,300);ctx.save();ctx.filter=p>.2&&p<.85?'brightness(0) invert(1)':'';Art.drawMon(ctx,p<.8?key:next,180,150,220*(1+Math.sin(p*Math.PI)*.16),'Idle',0,t/1000);ctx.restore();if(p<1)requestAnimationFrame(draw);else this.finish()};requestAnimationFrame(draw)}
 cancel(){const g=this.g;if(!this.pending)return;const key=this.pending.key;profile(g.state,key).evolutionDeclinedLevel=level(profile(g.state,key));this.pending=null;this.busy=false;g.save();g.closeModal(true);g.lab.key=key;g.lab.tab='level';g.lab.open(key)}
 async finish(){if(!this.pending)return;const g=this.g,{key,index}=this.pending;this.pending=null;const target=String(g.poke(key).evolutions[index].id)+(key.endsWith('s')?'s':''),firstLegendary=g.poke(target).rarity==='legendary'&&!g.state.roster.some(k=>parseInt(k)===parseInt(target))&&!g.state.legendaryStories.seen.includes(parseInt(target));const next=evolvePokemon(g.dex,g.state,key,g.poke(key).evolutions[index]);this.busy=false;g.save();g.closeModal(true);g.render();if(next){g.audio.chime('epic');g.toast('Félicitations ! '+g.poke(key).name+' est devenu '+g.poke(next).name+'.');if(firstLegendary){const id=parseInt(next);if(!g.state.legendaryStories.pending.some(p=>p.id===id))g.state.legendaryStories.pending.push({id,key:next});g.save();this.busy=true;try{await g.cinema.play({key:next})}finally{this.busy=false}}g.lab.key=next;g.lab.tab='level';g.lab.open(next)}else g.toast('Les conditions d’évolution ont changé. Aucun objet consommé.')}
}
